import java.util.*;

class Solution {
  public List<List<Integer>> verticalOrder(TreeNode root) {
    List<List<Integer>> ans = new ArrayList<>();
    if (root == null) return ans;
    // BFS keeps top-to-bottom, left-to-right order within each column
    TreeMap<Integer, List<Integer>> cols = new TreeMap<>();
    Deque<TreeNode> nodes = new ArrayDeque<>();
    Deque<Integer> idx = new ArrayDeque<>();
    nodes.add(root);
    idx.add(0);
    while (!nodes.isEmpty()) {
      TreeNode node = nodes.poll();
      int c = idx.poll();
      cols.computeIfAbsent(c, k -> new ArrayList<>()).add(node.val);
      if (node.left != null) {
        nodes.add(node.left);
        idx.add(c - 1);
      }
      if (node.right != null) {
        nodes.add(node.right);
        idx.add(c + 1);
      }
    }
    ans.addAll(cols.values());
    return ans;
  }
}
